#!/bin/bash# =============================================================================#  postgres-promote-replica.sh#  Manual PostgreSQL Replica Promotion#  Sistema Nacional de Cómputo Electoral Bolivia — Módulo 01##  Use this script to MANUALLY promote postgres-replica to PRIMARY when#  the automatic monitor is not running or when you want direct control.##  Usage:#    bash scripts/postgres-promote-replica.sh##  After promotion, run:#    bash scripts/postgres-rejoin-old-primary.sh#    (to re-initialize the old primary as a standby of the promoted replica)# =============================================================================set -eREPLICA_CONTAINER="${REPLICA_CONTAINER:-postgres-replica}"PG_USER="${PG_USER:-oep_user}"PG_DB="${PG_DB:-oep_oficial}"echo "======================================================================"echo "  Manual PostgreSQL Failover — Promote Replica"echo "  Sistema Nacional de Cómputo Electoral Bolivia"echo "======================================================================"echo ""# ── Step 1: Verify the replica container is running ──echo "Checking if $REPLICA_CONTAINER is running..."if ! docker ps --format '{{.Names}}' | grep -q "^${REPLICA_CONTAINER}$"; then    echo "ERROR: Container '$REPLICA_CONTAINER' is not running."    echo "       Run: docker compose ps"    exit 1fi# ── Step 2: Check current recovery state ──echo "Checking pg_is_in_recovery() on $REPLICA_CONTAINER..."IN_RECOVERY=$(docker exec "$REPLICA_CONTAINER" \    psql -U "$PG_USER" -d "$PG_DB" -tAq \    -c "SELECT pg_is_in_recovery();" 2>/dev/null || echo "error")if [ "$IN_RECOVERY" = "error" ]; then    echo "ERROR: Could not connect to $REPLICA_CONTAINER."    echo "       Check container status: docker logs $REPLICA_CONTAINER"    exit 1fiif [ "$IN_RECOVERY" = "f" ]; then    echo ""    echo "INFO: $REPLICA_CONTAINER is already a PRIMARY (pg_is_in_recovery() = false)."    echo "      No promotion needed."    echo ""    echo "Current cluster_status:"    docker exec "$REPLICA_CONTAINER" psql -U "$PG_USER" -d "$PG_DB" \        -c "SELECT nodo, rol, estado, ultima_verificacion FROM cluster_status WHERE motor = 'POSTGRESQL';" \        2>/dev/null || true    exit 0fiecho "OK: $REPLICA_CONTAINER is currently a STANDBY (pg_is_in_recovery() = true)."echo ""echo "This script will promote it to PRIMARY."echo "After promotion:"echo "  - postgres-replica becomes the new writable PRIMARY"echo "  - postgres-primary (old primary) must be re-joined manually"echo "  - Run: bash scripts/postgres-rejoin-old-primary.sh"echo ""read -p "Type YES to continue with promotion: " CONFIRMif [ "$CONFIRM" != "YES" ]; then    echo "Aborted."    exit 0fi# ── Step 3: Promote ──echo ""echo "Promoting $REPLICA_CONTAINER to PRIMARY..."docker exec "$REPLICA_CONTAINER" \    psql -U "$PG_USER" -d "$PG_DB" \    -c "SELECT pg_promote();"echo "Waiting for promotion to take effect (3s)..."sleep 3# ── Step 4: Verify ──IN_RECOVERY_AFTER=$(docker exec "$REPLICA_CONTAINER" \    psql -U "$PG_USER" -d "$PG_DB" -tAq \    -c "SELECT pg_is_in_recovery();" 2>/dev/null || echo "error")echo ""if [ "$IN_RECOVERY_AFTER" = "f" ]; then    echo "======================================================================"    echo "  PROMOTION SUCCESSFUL"    echo "======================================================================"    echo ""    echo "  $REPLICA_CONTAINER is now PRIMARY (pg_is_in_recovery() = false)"    echo ""    echo "Next steps:"    echo "  1. Update application connection strings:"    echo "       POSTGRES_PRIMARY_URL=...@postgres-replica:5432/oep_oficial"    echo ""    echo "  2. Re-join the old primary as standby:"    echo "       bash scripts/postgres-rejoin-old-primary.sh"    echo ""    echo "  3. Verify replication after rejoin:"    echo "       docker exec postgres-replica psql -U oep_user -d oep_oficial \\"    echo "         -c \"SELECT * FROM pg_stat_replication;\""    echo ""elif [ "$IN_RECOVERY_AFTER" = "t" ]; then    echo "WARNING: Promotion command ran but pg_is_in_recovery() is still true."    echo "         Check logs: docker logs $REPLICA_CONTAINER"    exit 1else    echo "ERROR: Could not verify promotion status."    echo "       Check logs: docker logs $REPLICA_CONTAINER"    exit 1fi